SELECT percentile_cont(0.75) within GROUP (ORDER BY AVG(value)) AS percentile FROM labevents JOIN patients ON labevents.subject_id = patients.subject_id JOIN icustays ON labevents.subject_id = icustays.subject_id WHERE patients.gender = 'F' AND EXTRACT(YEAR FROM age(CURRENT_DATE, patients.dob)) = 42 AND EXTRACT(YEAR FROM icustays.intime) BETWEEN 2015 AND 2016 AND itemid = 10175 AND value IS NOT NULL;